// Pomodoro Timer
const workDuration = 25 * 60; // seconds
const shortBreakDuration = 5 * 60;
const longBreakDuration = 15 * 60;
let mode = 'work';
let remaining = workDuration;
let timerInterval = null;
let workSessions = 0; // count of completed work sessions

const modeTitle = document.getElementById('mode-title');
const timeDisplay = document.getElementById('time-display');
const startBtn = document.getElementById('start-btn');
const pauseBtn = document.getElementById('pause-btn');
const resetBtn = document.getElementById('reset-btn');
const modeSelect = document.getElementById('mode-select');

function formatTime(seconds){
  const mins = String(Math.floor(seconds/60)).padStart(2,'0');
  const secs = String(seconds%60).padStart(2,'0');
  return `${mins}:${secs}`;
}

function updateUI(){
  timeDisplay.textContent = formatTime(remaining);
  modeTitle.textContent = mode.replace(/-/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
}

function playBeep(){
  const ctx = new (window.AudioContext || window.webkitAudioContext)();
  const oscillator = ctx.createOscillator();
  const gainNode = ctx.createGain();
  oscillator.connect(gainNode);
  gainNode.connect(ctx.destination);
  oscillator.type = 'sine';
  oscillator.frequency.setValueAtTime(600, ctx.currentTime);
  oscillator.start();
  setTimeout(()=>{oscillator.stop();},200);
}

function switchMode(){
  if(mode === 'work'){
    workSessions++;
    if(workSessions % 4 === 0){
      mode = 'long-break';
      remaining = longBreakDuration;
    } else {
      mode = 'short-break';
      remaining = shortBreakDuration;
    }
  } else {
    mode = 'work';
    remaining = workDuration;
  }
  modeSelect.value = mode;
  resetTimer(false);
}

function startTimer(){
  if(timerInterval) return;
  timerInterval = setInterval(()=>{
    if(remaining <= 0){
      clearInterval(timerInterval);
      timerInterval = null;
      playBeep();
      switchMode();
    } else {
      remaining--;
      updateUI();
    }
  },1000);
  startBtn.disabled=true; pauseBtn.disabled=false;
}

function pauseTimer(){
  if(timerInterval){
    clearInterval(timerInterval);
    timerInterval=null;
    startBtn.disabled=false; pauseBtn.disabled=true;
  }
}

function resetTimer(resetAll=true){
  pauseTimer();
  if(resetAll){
    mode = modeSelect.value || 'work';
  }
  if(mode==='work') remaining=workDuration;
  else if(mode==='short-break') remaining=shortBreakDuration;
  else if(mode==='long-break') remaining=longBreakDuration;
  updateUI();
}

modeSelect.addEventListener('change',e=>{
  mode=e.target.value;
  resetTimer(false);
});

startBtn.addEventListener('click',startTimer);
pauseBtn.addEventListener('click',pauseTimer);
resetBtn.addEventListener('click',()=>resetTimer());

updateUI();

